def tool_input_of(raw):
    """The tool's arguments as a dict, decoding the JSON-string form some vendors send."""
    if isinstance(raw, dict):
        return raw
    if isinstance(raw, str) and raw[:1] == "{":
        try:
            parsed = _json.loads(raw)
        except Exception:
            return {}
        if isinstance(parsed, dict):
            return parsed
    return {}


